// === sf-config-manager Step 1: IP检测 + 单例锁 + 分路径 + 登录请求 ===
var DEBUG = global.get('edge_debug') || false;
var isReauth = (msg.payload && msg.payload.action === 'reauth');
var existingJwt = global.get('edge_jwt') || '';

// === Singleton lock (60s expiry) ===
var lock = global.get('edge_config_manager_lock');
if (lock && (Date.now() - lock.ts < 60000)) {
    if (isReauth) {
        // Reauth: wait until current init finishes (max 30s)
        if (Date.now() - lock.ts < 30000) {
            if (DEBUG) node.warn('[CM] Re-auth waiting for active init (' + (Date.now() - lock.ts) + 'ms old)');
            setTimeout(function () { node.send(msg); }, 2000);
            return null;
        }
        // Force takeover after 30s
        if (DEBUG) node.warn('[CM] Lock expired, force takeover for reauth');
    } else {
        if (DEBUG) node.warn('[CM] Another init in progress, skip');
        return null;
    }
}
global.set('edge_config_manager_lock', { ts: Date.now(), nodeId: node.id });

// === Reauth guard: skip if JWT still valid and config ready ===
if (isReauth && existingJwt && global.get('edge_configReady')) {
    if (DEBUG) node.warn('[CM] Re-auth skipped, session still valid');
    return null;
}

var isFirstRun = !existingJwt && !isReauth;
var isRefresh = !isReauth && !isFirstRun;

// === IP Detection (skip virtual NICs) ===
var detectedIp = '127.0.0.1';
try {
    var os = global.get('os');
    if (os) {
        var nets = os.networkInterfaces();
        var VIRTUAL_PREFIXES = ['172.17.', '192.168.56.', '169.254.'];
        function isVirtual(addr) {
            for (var i = 0; i < VIRTUAL_PREFIXES.length; i++) {
                if (addr.indexOf(VIRTUAL_PREFIXES[i]) === 0) return true;
            }
            return false;
        }
        var candidates = [];
        for (var name in nets) {
            if (!nets.hasOwnProperty(name)) continue;
            var iface = nets[name];
            for (var i = 0; i < iface.length; i++) {
                var netInfo = iface[i];
                if (netInfo.family === 'IPv4' && !netInfo.internal && !isVirtual(netInfo.address)) {
                    candidates.push(netInfo.address);
                }
            }
        }
        for (var j = 0; j < candidates.length; j++) {
            if (candidates[j].indexOf('192.168.') === 0 || candidates[j].indexOf('10.') === 0) {
                detectedIp = candidates[j];
                break;
            }
        }
        if (detectedIp === '127.0.0.1' && candidates.length > 0) {
            detectedIp = candidates[0];
            if (DEBUG) node.warn('[CM] No 192.168/10.x, using ' + detectedIp);
        }
    }
} catch (e) {
    if (DEBUG) node.warn('[CM] IP detection failed: ' + e.message);
}

var hostPcIp = detectedIp !== '127.0.0.1' ? detectedIp : (global.get('edge_hostPcIp') || '127.0.0.1');
global.set('edge_hostPcIp', hostPcIp);

// === Default config (allow settings.js overrides) ===
global.set('edge_backendHost', global.get('edge_backendHost') || '127.0.0.1');
global.set('edge_backendPort', global.get('edge_backendPort') || 9099);
global.set('edge_apiKey', global.get('edge_apiKey') || '');
global.set('edge_backendUser', global.get('edge_backendUser') || 'admin');
global.set('edge_backendPass', global.get('edge_backendPass') || '');
global.set('edge_debug', DEBUG);

// === First run: initialize all state globals ===
if (isFirstRun) {
    global.set('edge_devices', []);
    global.set('edge_tagConfigs', {});
    global.set('edge_commStatus', {});
    global.set('edge_lastGoodTags', {});
    global.set('edge_historyData', {});
    global.set('edge_pg_queue', []);
    global.set('edge_pg_success_count', 0);
    global.set('edge_commPending', []);
    global.set('edge_lastBadSend', {});
    global.set('edge_handshakeFlags', {});
    global.set('edge_triggerLastRaw', {});
    global.set('edge_triggerForceTimes', {});
    global.set('edge_recentAlerts', []);
    global.set('edge_lastAlarmTime', {});
    global.set('edge_startTime', new Date().toISOString());
    global.set('edge_configReady', false);
    global.set('edge_reauthInProgress', false);
    if (DEBUG) node.warn('[CM] First run, hostPcIp=' + hostPcIp);
}

// === Refresh path: keep configReady=true, don't interrupt collection ===
if (isRefresh) {
    if (DEBUG) node.warn('[CM] Periodic refresh, configReady stays true');
}

// === Reauth path: clear JWT, full re-login ===
if (isReauth) {
    global.set('edge_jwt', '');
    global.set('edge_configReady', false);
    global.set('edge_reauthInProgress', true);
    if (DEBUG) node.warn('[CM] 401 reauth, full re-login');
}

// === Build login request ===
var user = global.get('edge_backendUser');
var pass = global.get('edge_backendPass');
var host = global.get('edge_backendHost');
var port = global.get('edge_backendPort');

msg.url = 'http://' + host + ':' + port + '/login';
msg.payload = 'username=' + encodeURIComponent(user) + '&password=' + encodeURIComponent(pass);

return msg;

// === sf-config-manager Step 2: JWT解析 + nodeId反查 + 拉取全局点位 + 分组输出 ===
var http = global.get('http');
var HOST = global.get('edge_backendHost') || '127.0.0.1';
var PORT = global.get('edge_backendPort') || 9099;
var DEBUG = global.get('edge_debug') || false;
var myHostPcIp = global.get('edge_hostPcIp') || '127.0.0.1';
var apiKey = global.get('edge_apiKey') || '';

// 1. Parse JWT from login response
var jwtToken = '';
try {
    var r = JSON.parse(msg.payload);
    jwtToken = (r.data && r.data.token) ? r.data.token : (r.token || '');
} catch (e) {
    jwtToken = '';
}

if (!jwtToken) {
    if (DEBUG) node.warn('[CM] JWT FAIL: ' + (msg.payload || '').substring(0, 80));
    global.set('edge_reauthInProgress', false);
    // Retry after 10s
    setTimeout(function () {
        var retryMsg = { payload: {} };
        node.send([null, null]);
    }, 10000);
    return null;
}

global.set('edge_jwt', jwtToken);
global.set('edge_reauthInProgress', false);
if (DEBUG) node.warn('[CM] JWT OK, hostPcIp=' + myHostPcIp);

// 2. Discover/register nodeId via heartbeat
function discoverNodeId(callback) {
    var nodeParams = 'host_pc_ip=' + encodeURIComponent(myHostPcIp)
        + '&node_ip=' + encodeURIComponent(myHostPcIp)
        + '&running_flows=5&memory_usage_mb=' + (Math.round(((global.get('process')||{memoryUsage:function(){return{rss:0}}}).memoryUsage().rss||0)/1048576)||0);
    var nodeOpts = {
        hostname: HOST, port: PORT,
        path: '/monitor/heartbeat?' + nodeParams,
        method: 'POST',
        headers: {
            'X-API-Key': apiKey,
            'Authorization': 'Bearer ' + jwtToken,
            'Content-Type': 'application/json'
        }
    };

    var nr = http.request(nodeOpts, function (res) {
        var b = '';
        res.on('data', function (d) { b += d; });
        res.on('end', function () {
            try {
                var j = JSON.parse(b);
                var nid = (j.data && j.data.node_id) ? j.data.node_id : 0;
                if (nid > 0) {
                    global.set('edge_nodeId', nid);
                    if (DEBUG) node.warn('[CM] Node registered, nodeId=' + nid);
                    callback(nid);
                } else {
                    // Hash fallback
                    var hash = 0;
                    for (var i = 0; i < myHostPcIp.length; i++) {
                        hash = ((hash << 5) - hash) + myHostPcIp.charCodeAt(i);
                        hash |= 0;
                    }
                    nid = Math.abs(hash) % 9000 + 1000;
                    global.set('edge_nodeId', nid);
                    if (DEBUG) node.warn('[CM] nodeId from hash: ' + nid);
                    callback(nid);
                }
            } catch (e) {
                if (DEBUG) node.warn('[CM] nodeId parse err: ' + e.message);
                callback(0);
            }
        });
    });
    nr.setTimeout(5000, function () {
        nr.removeAllListeners();
        nr.destroy();
        if (DEBUG) node.warn('[CM] nodeId request timeout');
        callback(0);
    });
    nr.on('error', function (e) {
        if (DEBUG) node.warn('[CM] nodeId err: ' + e.message);
        callback(0);
    });
    nr.write('{}');
    nr.end();
}

// 3. Fetch global tag list + group by deviceId + filter
function discoverTags(nodeId) {
    var tagPath = '/plc/tag/global/list?page_size=10000';
    var tagReq = http.request({
        hostname: HOST, port: PORT, path: tagPath, method: 'GET',
        headers: { 'Authorization': 'Bearer ' + jwtToken }
    }, function (res) {
        var body = '';
        res.on('data', function (d) { body += d; });
        res.on('end', function () {
            try {
                var r = JSON.parse(body);
                if (r.code !== 200) {
                    node.warn('[CM] Tag API returned code ' + (r.code || 'unknown') + ', will retry on refresh');
                    global.set('edge_configReady', true);
                    node.send([null, null]);
                    return;
                }
                var records = r.rows || [];
                if (records.length === 0) {
                    node.warn('[CM] No tags in system');
                    global.set('edge_configReady', true);
                    node.send([null, null]);
                    return;
                }

                // Group by deviceId
                var byDevice = {};
                records.forEach(function (t) {
                    var did = t.deviceId || 1;
                    var key = String(did);
                    if (!byDevice[key]) {
                        byDevice[key] = {
                            id: did,
                            deviceName: t.deviceName || ('PLC-' + did),
                            hostPcIp: t.hostPcIp || myHostPcIp,
                            plcIp: t.plcIp || '127.0.0.1',
                            plcPort: t.plcPort || 5007,
                            comType: t.comType || 'MC_Protocol',
                            protocolParams: {},
                            tags: [],
                            scanIntervalMs: t.scanIntervalMs || 1000,
                            commTimeoutMs: t.commTimeoutMs || 3000,
                            retryCount: t.retryCount || 2,
                            retryIntervalMs: t.retryIntervalMs || 500,
                            triggerKind: t.triggerKind || 1,
                            status: t.status || t.deviceStatus || '0'
                        };
                        // Merge protocolParams: backend JSON takes priority
                        var pp = {};
                        try {
                            if (t.protocolParams) {
                                pp = typeof t.protocolParams === 'string' ? JSON.parse(t.protocolParams) : t.protocolParams;
                            }
                        } catch (e) {}
                        if (Object.keys(pp).length === 0) {
                            pp = {
                                mcFrame: t.mcFrame || '3E',
                                stationNo: t.stationNo || 0,
                                networkNo: t.networkNo || 0,
                                plcSeries: t.plcSeries || 'Q'
                            };
                        }
                        byDevice[key].protocolParams = pp;
                    }
                    // Parse address: octal for X/Y, decimal for D/W/M etc.
                    var addrStr = String(t.registerAddress || '0').replace(/\D/g, '');
                    var base = (t.registerType === 'X' || t.registerType === 'Y') ? 8 : 10;
                    var addr = parseInt(addrStr, base) || 0;

                    byDevice[key].tags.push({
                        id: t.id,
                        addr: addr,
                        regAddr: t.registerAddress || '',
                        regType: t.registerType || 'D',
                        name: t.tagName,
                        dataType: t.dataType || 'INT16',
                        tform: t.transformType || 'none',
                        slope: t.transformSlopeA || 1,
                        offset: t.transformOffsetB || 0,
                        unit: t.engUnit || '',
                        deadband: t.reportDeadbandMs || 0,
                        reportForceIntervalMs: t.reportForceIntervalMs || 5000
                    });
                });

                // Filter: only enabled devices on this PC
                var myDevices = [];
                var myTagConfigs = {};
                Object.keys(byDevice).forEach(function (did) {
                    var dev = byDevice[did];
                    if (String(dev.status) !== '0') return;
                    if (dev.hostPcIp !== myHostPcIp) return;
                    // MC devices need at least one valid register
                    if (dev.comType === 'MC_Protocol') {
                        var validTags = dev.tags.filter(function (t) { return t.addr >= 0; });
                        if (validTags.length === 0) {
                            if (DEBUG) node.warn('[CM] Device ' + dev.deviceName + ' has no valid registers, skipped');
                            return;
                        }
                    }

                    // Set timeout/retry on device object
                    dev.timeout = dev.commTimeoutMs;
                    dev.maxRetries = dev.retryCount;
                    dev.retryInterval = dev.retryIntervalMs;

                    myDevices.push(dev);
                    myTagConfigs[dev.id] = dev.tags;
                });

                global.set('edge_devices', myDevices);
                global.set('edge_tagConfigs', myTagConfigs);
                global.set('edge_configReady', true);

                if (DEBUG) {
                    node.warn('[CM] Discovered ' + myDevices.length + ' devices (nodeId=' + nodeId + '):');
                    myDevices.forEach(function (d) {
                        node.warn('  ' + d.deviceName + ' (' + d.plcIp + ':' + d.plcPort + ') ' + d.tags.length + ' tags comType=' + d.comType);
                    });
                }

                // Output 1: config for main flow scheduler
                var configMsg = {
                    payload: {
                        jwt: jwtToken,
                        nodeId: nodeId,
                        hostPcIp: myHostPcIp,
                        devices: myDevices
                    }
                };

                // Output 2: MQTT node online
                var now = new Date().toISOString();
                var devList = myDevices.map(function (d) {
                    return { device_id: d.id, device_name: d.deviceName, tag_count: d.tags.length };
                });
                var mqttMsg = {
                    topic: 'edgelink-v10/nodes/' + nodeId + '/status',
                    payload: JSON.stringify({
                        node_id: nodeId,
                        host_pc_ip: myHostPcIp,
                        status: 'online',
                        device_count: myDevices.length,
                        devices: devList,
                        ts: now
                    }),
                    qos: 1,
                    retain: true
                };

                node.send([configMsg, mqttMsg]);
                if (DEBUG) node.warn('[CM] Config complete, ' + myDevices.length + ' devices ready');

            } catch (e) {
                if (DEBUG) node.warn('[CM] Tag parsing error: ' + e.message);
                node.send([null, null]);
            }
        });
    });

    tagReq.on('error', function (e) {
        node.warn('[CM] Tag fetch error: ' + e.message);
        global.set('edge_configReady', true);
        node.send([null, null]);
    });
    tagReq.setTimeout(10000, function () {
        tagReq.removeAllListeners();
        tagReq.destroy();
        node.warn('[CM] Tag fetch timeout');
        global.set('edge_configReady', true);
        node.send([null, null]);
    });
    tagReq.end();
}

// Execute: nodeId → tags
discoverNodeId(function (nid) {
    discoverTags(nid);
});

return null;

nodes.info:
三菱 MC 协议驱动 (3E/4E帧 + 位元件拆包 + 模拟模式)

输入: msg.payload = { id, deviceName, plcIp, plcPort, protocolParams, tags[], timeout, maxRetries, retryInterval }
输出: msg.payload = { deviceId, deviceName, success, data, error, driverType, plcIp, plcPort }

v10 Phase 1a — 独立可测，不依赖后端

nodes.func:
// === sf-mc-driver v10: 3E/4E帧 + 位元件拆包 + 智能批量 + 模拟模式 ===
var net = global.get('net');
var SIM_MODE = global.get('edge_simulationMode') || false;
var DEBUG = global.get('edge_debug') || false;

var dev = msg.payload;
if (!dev || !dev.id) {
    node.warn('[MC-Driver] Invalid input, missing device id');
    return null;
}

// === Singleton lock (60s expiry) ===
var lock = global.get('edge_mc_driver_lock');
if (lock && (Date.now() - lock.ts < 60000) && lock.instanceId !== node.id) {
    if (DEBUG) node.warn('[MC-Driver] Another instance running (' + lock.instanceId + '), requeue');
    setTimeout(function () { node.send(msg); }, 200);
    return null;
}
global.set('edge_mc_driver_lock', { ts: Date.now(), instanceId: node.id });

var pp = dev.protocolParams || {};
var mcFrame = pp.mcFrame || '3E';
var roundStart = Date.now();

// === MC Device Code Map ===
var MC_DEVICE_CODES = {
    'D': 0xA8, 'W': 0xB4, 'X': 0x9C, 'Y': 0x9D,
    'M': 0x90, 'L': 0x92, 'B': 0xA0, 'R': 0xAF
};
var BIT_DEVICES = { 'X': true, 'Y': true, 'M': true, 'L': true, 'B': true };

// === Simulation Mode ===
if (SIM_MODE || !net) {
    setTimeout(function () {
        var simData = {};
        (dev.tags || []).forEach(function (t) {
            simData[t.id] = {
                rawValue: BIT_DEVICES[t.regType] ? (Math.random() > 0.5 ? 1 : 0) : Math.floor(Math.random() * 1000),
                quality: 0,
                ts: new Date().toISOString()
            };
        });
        var ok = Math.random() > 0.1;
        msg.payload = {
            deviceId: dev.id,
            deviceName: dev.deviceName,
            success: ok,
            data: simData,
            error: ok ? null : 'Simulated timeout',
            driverType: 'driver-mc-protocol',
            plcIp: dev.plcIp,
            plcPort: dev.plcPort,
            roundTimeMs: Date.now() - roundStart
        };
        node.status({
            fill: ok ? 'green' : 'red',
            shape: 'dot',
            text: dev.deviceName + ' SIM ' + (ok ? 'OK' : 'FAIL')
        });
        node.send(msg);
    }, 10 + Math.random() * 30);
    return null;
}

// ===== Real TCP Mode =====

// Step 1: Group tags by register type + address proximity clustering
var byRegType = {};
(dev.tags || []).forEach(function (t) {
    var rt = t.regType || 'D';
    if (!byRegType[rt]) byRegType[rt] = [];
    byRegType[rt].push(t);
});

var regGroups = [];
var MAX_GAP = 20;
var MAX_CLUSTER = 50;
Object.keys(byRegType).forEach(function (rt) {
    var tags = byRegType[rt].sort(function (a, b) { return a.addr - b.addr; });
    var cluster = [tags[0]];
    for (var i = 1; i < tags.length; i++) {
        var gap = tags[i].addr - cluster[cluster.length - 1].addr;
        if (gap <= MAX_GAP && cluster.length < MAX_CLUSTER) {
            cluster.push(tags[i]);
        } else {
            regGroups.push({ regType: rt, tags: cluster });
            cluster = [tags[i]];
        }
    }
    if (cluster.length > 0) regGroups.push({ regType: rt, tags: cluster });
});

if (regGroups.length === 0) {
    msg.payload = {
        deviceId: dev.id, deviceName: dev.deviceName,
        success: false, data: {}, error: 'No valid register groups',
        driverType: 'driver-mc-protocol', plcIp: dev.plcIp, plcPort: dev.plcPort,
        roundTimeMs: Date.now() - roundStart
    };
    node.send(msg);
    return null;
}

if (DEBUG) node.warn('[MC-Driver] ' + dev.deviceName + ' groups=' + regGroups.length + ' frame=' + mcFrame);

// Step 2: Build MC Frame
function buildMCFrame(startAddr, wordCount, stationNo, regType, frameType) {
    var deviceCode = MC_DEVICE_CODES[regType] || 0xA8;
    if (frameType === '4E') {
        var hasSN = (pp.serialNo != null && pp.serialNo !== 0);
        var bufLen = hasSN ? 24 : 22;
        var buf = Buffer.alloc(bufLen);
        buf[0] = 0x54; buf[1] = 0x00;
        buf[2] = pp.networkNo || 0;
        buf[3] = 0xFF;
        buf[4] = 0xFF; buf[5] = 0x03;
        buf[6] = stationNo || 0;
        buf[7] = hasSN ? 0x0F : 0x0D; buf[8] = 0x00;
        buf[9] = 0x10; buf[10] = 0x00;
        var off = 11;
        if (hasSN) { buf[off] = pp.serialNo & 0xFF; buf[off + 1] = (pp.serialNo >> 8) & 0xFF; off += 2; }
        buf[off] = 0x01; buf[off + 1] = 0x04; off += 2;
        buf[off] = 0x00; buf[off + 1] = 0x00; off += 2;
        buf.writeUInt32LE(startAddr, off); off += 4;
        buf[off] = deviceCode; off += 1;
        buf.writeUInt16LE(wordCount, off);
        return buf;
    }
    // 3E frame (21 bytes)
    var buf = Buffer.alloc(21);
    buf[0] = 0x50; buf[1] = 0x00;
    buf[2] = 0x00; buf[3] = 0xFF; buf[4] = 0xFF; buf[5] = 0x03;
    buf[6] = stationNo || 0; buf[7] = 0x0C; buf[8] = 0x00;
    buf[9] = 0x10; buf[10] = 0x00;
    buf[11] = 0x01; buf[12] = 0x04;
    buf[13] = 0x00; buf[14] = 0x00;
    buf[15] = startAddr & 0xFF;
    buf[16] = (startAddr >> 8) & 0xFF;
    buf[17] = (startAddr >> 16) & 0xFF;
    buf[18] = deviceCode;
    buf.writeUInt16LE(wordCount, 19);
    return buf;
}

// Step 3: Parse MC Response
function parseMCResponse(buf, startAddr, regType) {
    if (!buf || buf.length < 11) return null;
    var subheader = (buf[0] === 0xD0) ? 0x50 : ((buf[0] === 0xD4) ? 0xD4 : 0);
    if (subheader === 0) return null;
    var endCode = buf.readUInt16LE(9);
    if (endCode !== 0) return null;
    var dataLen = buf.readUInt16LE(7) - 2;
    var dataStart = (mcFrame === '4E' && pp.serialNo != null && pp.serialNo !== 0) ? 13 : 11;
    if (buf.length < dataStart + dataLen) return null;
    var result = {};
    if (BIT_DEVICES[regType]) {
        for (var w = 0; w < dataLen / 2; w++) {
            var wordVal = buf.readUInt16LE(dataStart + w * 2);
            for (var b = 0; b < 16; b++) {
                result[regType + (startAddr + w * 16 + b)] = (wordVal >> b) & 1;
            }
        }
    } else {
        for (var i = 0; i < dataLen / 2; i++) {
            result[regType + (startAddr + i)] = buf.readInt16LE(dataStart + i * 2);
        }
    }
    return result;
}

// Step 4: Process groups sequentially
var allStdData = {};
var hasFailed = false;
var firstError = '';
var timeout = dev.timeout || 3000;
var maxRetries = dev.maxRetries || 2;
var retryInterval = dev.retryInterval || 300;

function processGroup(gi) {
    if (gi >= regGroups.length) {
        // All groups done
        var roundTimeMs = Date.now() - roundStart;
        if (DEBUG) node.warn('[MC-Driver] ' + dev.deviceName + ' done in ' + roundTimeMs + 'ms, groups=' + regGroups.length + ' failed=' + hasFailed);
        msg.payload = {
            deviceId: dev.id,
            deviceName: dev.deviceName,
            success: !hasFailed,
            data: allStdData,
            error: hasFailed ? firstError : null,
            driverType: 'driver-mc-protocol',
            plcIp: dev.plcIp,
            plcPort: dev.plcPort,
            roundTimeMs: roundTimeMs
        };
        node.status({
            fill: hasFailed ? 'red' : 'green',
            shape: 'dot',
            text: dev.deviceName + ' ' + Object.keys(allStdData).length + ' vals'
        });
        node.send(msg);
        return;
    }

    var grp = regGroups[gi];
    var addrs = grp.tags.map(function (t) { return t.addr; });
    var startA = addrs[0];
    var isBit = BIT_DEVICES[grp.regType] || false;
    var wordCount;
    if (isBit) {
        wordCount = Math.ceil((addrs[addrs.length - 1] - startA + 1) / 16);
    } else {
        wordCount = addrs[addrs.length - 1] - startA + 1;
    }

    function attemptGroup(attempt) {
        if (attempt > maxRetries) {
            hasFailed = true;
            if (!firstError) firstError = 'MC read failed for ' + grp.regType + startA;
            setImmediate(function () { processGroup(gi + 1); });
            return;
        }

        var client = new net.Socket();
        var buf = Buffer.alloc(0);
        var resolved = false;

        client.setTimeout(timeout);

        client.connect(dev.plcPort, dev.plcIp, function () {
            var frame = buildMCFrame(startA, wordCount, pp.stationNo || 0, grp.regType, mcFrame);
            client.write(frame);
        });

        client.on('data', function (chunk) {
            buf = Buffer.concat([buf, chunk]);
            var hdrLen = (mcFrame === '4E' && pp.serialNo != null && pp.serialNo !== 0) ? 13 : 11;
            if (!resolved && buf.length >= hdrLen) {
                var dataLen = buf.readUInt16LE(7) - 2;
                if (buf.length >= hdrLen + dataLen) {
                    resolved = true;
                    var raw = parseMCResponse(buf, startA, grp.regType);
                    if (raw) {
                        grp.tags.forEach(function (t) {
                            var key = grp.regType + t.addr;
                            var rv = raw[key];
                            var q = 0;
                            if (rv === undefined || rv === null) q = 2;
                            allStdData[t.id] = {
                                rawValue: rv,
                                quality: q,
                                ts: new Date().toISOString()
                            };
                        });
                        try { client.destroy(); } catch (e) {}
                        setImmediate(function () { processGroup(gi + 1); });
                    } else {
                        try { client.destroy(); } catch (e) {}
                        setTimeout(function () { attemptGroup(attempt + 1); }, retryInterval);
                    }
                }
            }
        });

        client.on('timeout', function () {
            if (resolved) return;
            resolved = true;
            try { client.destroy(); } catch (e) {}
            setTimeout(function () { attemptGroup(attempt + 1); }, retryInterval);
        });

        client.on('error', function (e) {
            if (resolved) return;
            resolved = true;
            try { client.destroy(); } catch (e2) {}
            setTimeout(function () { attemptGroup(attempt + 1); }, retryInterval);
        });

        client.on('close', function () {
            if (!resolved) {
                resolved = true;
                if (buf.length === 0) {
                    hasFailed = true;
                    if (!firstError) firstError = 'TCP closed (no data)';
                    setImmediate(function () { processGroup(gi + 1); });
                } else {
                    try { client.destroy(); } catch (e) {}
                    setTimeout(function () { attemptGroup(attempt + 1); }, retryInterval);
                }
            }
        });
    }

    attemptGroup(0);
}

processGroup(0);
return null;

// === sf-modbus-driver v10: MBAP+PDU + 字节序 + 模拟模式 ===
var net = global.get('net');
var SIM_MODE = global.get('edge_simulationMode') || false;
var DEBUG = global.get('edge_debug') || false;

var dev = msg.payload;
if (!dev || !dev.id) {
    node.warn('[MB-Driver] Invalid input, missing device id');
    return null;
}

// === Singleton lock (60s expiry) ===
var lock = global.get('edge_modbus_driver_lock');
if (lock && (Date.now() - lock.ts < 60000) && lock.instanceId !== node.id) {
    if (DEBUG) node.warn('[MB-Driver] Another instance running, requeue');
    setTimeout(function () { node.send(msg); }, 200);
    return null;
}
global.set('edge_modbus_driver_lock', { ts: Date.now(), instanceId: node.id });

var pp = dev.protocolParams || {};
var roundStart = Date.now();
var slaveId = pp.slaveId || 1;
var funcCode = pp.functionCode || 3;
var byteOrder = pp.byteOrder || 'ABCD';

// === Simulation Mode ===
if (SIM_MODE || !net) {
    setTimeout(function () {
        var simData = {};
        (dev.tags || []).forEach(function (t) {
            simData[t.id] = {
                rawValue: Math.floor(Math.random() * 65535) - 32768,
                quality: 0,
                ts: new Date().toISOString()
            };
        });
        var ok = Math.random() > 0.1;
        msg.payload = {
            deviceId: dev.id,
            deviceName: dev.deviceName,
            success: ok,
            data: simData,
            error: ok ? null : 'Simulated timeout',
            driverType: 'driver-modbus-tcp',
            plcIp: dev.plcIp,
            plcPort: dev.plcPort,
            roundTimeMs: Date.now() - roundStart
        };
        node.status({
            fill: ok ? 'green' : 'red',
            shape: 'dot',
            text: dev.deviceName + ' SIM ' + (ok ? 'OK' : 'FAIL')
        });
        node.send(msg);
    }, 10 + Math.random() * 30);
    return null;
}

// ===== Real TCP Mode =====

// Step 1: Group tags by register type (function code grouping)
var tags = dev.tags || [];
if (tags.length === 0) {
    msg.payload = {
        deviceId: dev.id, deviceName: dev.deviceName,
        success: false, data: {}, error: 'No tags',
        driverType: 'driver-modbus-tcp', plcIp: dev.plcIp, plcPort: dev.plcPort,
        roundTimeMs: Date.now() - roundStart
    };
    node.send(msg);
    return null;
}

// Cluster by address proximity (gap <= 20, max 125 registers per Modbus spec)
var sorted = tags.slice().sort(function (a, b) { return a.addr - b.addr; });
var groups = [];
var cluster = [sorted[0]];
var MAX_GAP = 20;
var MAX_REGS = 125;
for (var i = 1; i < sorted.length; i++) {
    var gap = sorted[i].addr - cluster[cluster.length - 1].addr;
    if (gap <= MAX_GAP && cluster.length < MAX_REGS) {
        cluster.push(sorted[i]);
    } else {
        groups.push(cluster);
        cluster = [sorted[i]];
    }
}
if (cluster.length > 0) groups.push(cluster);

if (DEBUG) node.warn('[MB-Driver] ' + dev.deviceName + ' groups=' + groups.length + ' slaveId=' + slaveId + ' byteOrder=' + byteOrder);

// Byte order helpers — reorder 4 bytes from 2 consecutive registers
function reorderBytes(r0_hi, r0_lo, r1_hi, r1_lo, order) {
    var b; // 4-byte array
    switch (order) {
        case 'BADC': b = [r0_lo, r0_hi, r1_lo, r1_hi]; break;
        case 'CDAB': b = [r1_hi, r1_lo, r0_hi, r0_lo]; break;
        case 'DCBA': b = [r1_lo, r1_hi, r0_lo, r0_hi]; break;
        default:     b = [r0_hi, r0_lo, r1_hi, r1_lo]; break; // ABCD
    }
    return Buffer.from(b);
}

function read16(hi, lo, order, signed) {
    var val;
    if (order === 'BADC' || order === 'DCBA') {
        val = (lo << 8) | hi;
    } else {
        val = (hi << 8) | lo;
    }
    if (signed && val > 32767) val = val - 65536;
    return val;
}

// Step 2: Build Modbus TCP frame
function buildModbusFrame(transactionId, unitId, startAddr, count) {
    var buf = Buffer.alloc(12);
    buf.writeUInt16BE(transactionId, 0);
    buf.writeUInt16BE(0, 2);           // Protocol ID
    buf.writeUInt16BE(6, 4);           // Length (remainder)
    buf[6] = slaveId;                   // Unit ID
    buf[7] = funcCode;                 // Function code
    buf.writeUInt16BE(startAddr, 8);   // Start address
    buf.writeUInt16BE(count, 10);      // Quantity
    return buf;
}

// Step 3: Parse Modbus response
function parseModbusResponse(buf, startAddr, count) {
    if (!buf || buf.length < 9) return null;
    var respFuncCode = buf[7];
    if (respFuncCode > 0x80) {
        return { error: 'Modbus exception ' + buf[8] };
    }
    var byteCount = buf[8];
    if (buf.length < 9 + byteCount) return null;
    var result = {};
    if (funcCode === 1 || funcCode === 2) {
        // Bit data: 1 byte = 8 bits (coils / discrete inputs)
        for (var i = 0; i < count; i++) {
            var byteIdx = 9 + Math.floor(i / 8);
            var bitIdx = i % 8;
            if (byteIdx >= buf.length) break;
            result['R' + (startAddr + i)] = { hi: 0, lo: (buf[byteIdx] >> bitIdx) & 1 };
        }
    } else {
        // Register data: 2 bytes per register (03/04)
        for (var i = 0; i < count; i++) {
            var offset = 9 + i * 2;
            if (offset + 1 >= buf.length) break;
            result['R' + (startAddr + i)] = { hi: buf[offset], lo: buf[offset + 1] };
        }
    }
    return { values: result };
}

// Step 4: Process groups sequentially
var allStdData = {};
var hasFailed = false;
var firstError = '';
var timeout = dev.timeout || 3000;
var maxRetries = dev.maxRetries || 2;
var retryInterval = dev.retryInterval || 300;
var txnId = Math.floor(Math.random() * 65535);

function processGroup(gi) {
    if (gi >= groups.length) {
        var roundTimeMs = Date.now() - roundStart;
        msg.payload = {
            deviceId: dev.id,
            deviceName: dev.deviceName,
            success: !hasFailed,
            data: allStdData,
            error: hasFailed ? firstError : null,
            driverType: 'driver-modbus-tcp',
            plcIp: dev.plcIp,
            plcPort: dev.plcPort,
            roundTimeMs: roundTimeMs
        };
        node.status({
            fill: hasFailed ? 'red' : 'green',
            shape: 'dot',
            text: dev.deviceName + ' ' + Object.keys(allStdData).length + ' vals'
        });
        node.send(msg);
        return;
    }

    var grp = groups[gi];
    var addrs = grp.map(function (t) { return t.addr; });
    var startA = addrs[0];
    var maxAddr = addrs[addrs.length - 1];
    // Expand range for 32-bit tags that need 2 registers
    grp.forEach(function (t) {
        var dt = t.dataType || 'INT16';
        if ((dt === 'FLOAT32' || dt === 'INT32' || dt === 'UINT32') && t.addr + 1 > maxAddr) {
            maxAddr = t.addr + 1;
        }
    });
    var wordCount = maxAddr - startA + 1;

    function attemptGroup(attempt) {
        if (attempt > maxRetries) {
            hasFailed = true;
            if (!firstError) firstError = 'Modbus read failed at addr ' + startA;
            setImmediate(function () { processGroup(gi + 1); });
            return;
        }

        var client = new net.Socket();
        var buf = Buffer.alloc(0);
        var resolved = false;

        client.setTimeout(timeout);

        var currentTxnId = (txnId + 1) & 0xFFFF;
        txnId = currentTxnId;
        client.connect(dev.plcPort, dev.plcIp, function () {
            var frame = buildModbusFrame(currentTxnId, slaveId, startA, wordCount);
            client.write(frame);
        });

        client.on('data', function (chunk) {
            buf = Buffer.concat([buf, chunk]);
            // Modbus TCP: MBAP header (6 bytes) + PDU
            if (!resolved && buf.length >= 7) {
                var mbapLen = buf.readUInt16BE(4);
                var expectedTotal = 6 + mbapLen;
                if (buf.length < expectedTotal) return;
                // Validate Transaction ID + Unit ID
                var respTxnId = buf.readUInt16BE(0);
                var respUnitId = buf[6];
                if (respTxnId !== currentTxnId || respUnitId !== slaveId) {
                    if (DEBUG) node.warn('[MB-Driver] TxnId/UnitId mismatch: exp ' + currentTxnId + '/' + slaveId + ' got ' + respTxnId + '/' + respUnitId);
                    buf = Buffer.alloc(0);  // Discard and wait for correct frame
                    return;
                }
                if (buf.length < 9) return;
                var byteCount = buf[8];
                if (buf.length >= expectedTotal) {
                    resolved = true;
                    var parsed = parseModbusResponse(buf, startA, wordCount);
                    if (parsed && parsed.values) {
                        grp.forEach(function (t) {
                            var key = 'R' + t.addr;
                            var reg = parsed.values[key];
                            var rv, q = 0;
                            if (!reg || reg.hi === undefined) { q = 2; rv = null; }
                            else {
                                var dt = t.dataType || 'INT16';
                                if (dt === 'FLOAT32' || dt === 'INT32' || dt === 'UINT32') {
                                    var reg2 = parsed.values['R' + (t.addr + 1)];
                                    if (!reg2) { q = 2; rv = null; }
                                    else {
                                        var b4 = reorderBytes(reg.hi, reg.lo, reg2.hi, reg2.lo, byteOrder);
                                        if (dt === 'FLOAT32') rv = parseFloat(b4.readFloatBE(0).toFixed(4));
                                        else if (dt === 'UINT32') rv = b4.readUInt32BE(0);
                                        else rv = b4.readInt32BE(0);
                                    }
                                } else if (dt === 'UINT16') {
                                    rv = read16(reg.hi, reg.lo, byteOrder, false);
                                } else {
                                    rv = read16(reg.hi, reg.lo, byteOrder, true);
                                }
                            }
                            allStdData[t.id] = {
                                rawValue: rv,
                                quality: q,
                                ts: new Date().toISOString()
                            };
                        });
                        try { client.destroy(); } catch (e) {}
                        setImmediate(function () { processGroup(gi + 1); });
                    } else if (parsed && parsed.error) {
                        hasFailed = true;
                        if (!firstError) firstError = parsed.error;
                        try { client.destroy(); } catch (e) {}
                        setImmediate(function () { processGroup(gi + 1); });
                    } else {
                        try { client.destroy(); } catch (e) {}
                        setTimeout(function () { attemptGroup(attempt + 1); }, retryInterval);
                    }
                }
            }
        });

        client.on('timeout', function () {
            if (resolved) return;
            resolved = true;
            try { client.destroy(); } catch (e) {}
            setTimeout(function () { attemptGroup(attempt + 1); }, retryInterval);
        });

        client.on('error', function (e) {
            if (resolved) return;
            resolved = true;
            try { client.destroy(); } catch (e2) {}
            setTimeout(function () { attemptGroup(attempt + 1); }, retryInterval);
        });

        client.on('close', function () {
            if (!resolved) {
                resolved = true;
                if (buf.length === 0) {
                    hasFailed = true;
                    if (!firstError) firstError = 'TCP closed (no data)';
                    setImmediate(function () { processGroup(gi + 1); });
                } else {
                    try { client.destroy(); } catch (e) {}
                    setTimeout(function () { attemptGroup(attempt + 1); }, retryInterval);
                }
            }
        });
    }

    attemptGroup(0);
}

processGroup(0);
return null;

// === sf-data-processor v10: 换算 + 死区 + 质量码 + 历史 + 双输出 ===
var result = msg.payload;
if (!result) { node.send([null, null]); return; }

// === Per-device processing guard (prevents read-modify-write race) ===
var procGuard = global.get('edge_proc_guard') || {};
var guardEntry = procGuard[result.deviceId];
// If locked but expired (>30s), force release (uncaught exception recovery)
if (guardEntry && (Date.now() - guardEntry.ts > 30000)) {
    delete procGuard[result.deviceId];
    guardEntry = undefined;
}
if (guardEntry) {
    // Drop duplicate — scheduler will re-collect this device next cycle
    return;
}
procGuard[result.deviceId] = { ts: Date.now() };

var nodeId = global.get('edge_nodeId') || 999;
var hostPcIp = global.get('edge_hostPcIp') || '127.0.0.1';
var tagConfigs = global.get('edge_tagConfigs') || {};
var devTags = tagConfigs[result.deviceId] || [];
var now = new Date().toISOString();
var nowMs = Date.now();
var DEBUG = global.get('edge_debug') || false;

// === State references ===
var lastGoodTags = global.get('edge_lastGoodTags') || {};
var historyData = global.get('edge_historyData') || {};
var commStatus = global.get('edge_commStatus') || {};
var commPending = global.get('edge_commPending') || [];
var lastBadSend = global.get('edge_lastBadSend') || {};

var devId = result.deviceId;
var devName = result.deviceName || ('PLC-' + devId);

// ===== FAILURE PATH =====
if (!result.success) {
    var status = commStatus[devId] || { consecutiveFails: 0, lastState: 'online' };
    status.consecutiveFails = (status.consecutiveFails || 0) + 1;
    status.lastFailTime = nowMs;

    // P0-3: Only push to pending on state change (online → offline)
    if (status.lastState !== 'offline') {
        status.lastState = 'offline';
        commPending.push({
            deviceId: devId,
            success: false,
            error: result.error || 'communication failure',
            consecutiveFails: status.consecutiveFails,
            ts: now
        });
        global.set('edge_commPending', commPending);
        if (DEBUG) node.warn('[DP] Device ' + devName + ' state: online → offline');
        // Publish PLC_OFFLINE alarm via MQTT (v9.1 parity)
        var alarmMsg = {
            topic: 'edgelink/alarm/plc_offline/' + devId,
            payload: JSON.stringify({
                alert_type: 'PLC_OFFLINE',
                node_id: nodeId,
                device_id: devId,
                device_name: devName,
                host_pc_ip: hostPcIp,
                msg: devName + ' communication failure: ' + (result.error || 'unknown'),
                ts: now
            }),
            qos: 1,
            retain: false
        };
        var alerts = global.get('edge_recentAlerts') || [];
        alerts.push({
            alertType: 'PLC_OFFLINE',
            deviceId: devId,
            deviceName: devName,
            msg: result.error || 'communication failure',
            ts: now
        });
        if (alerts.length > 20) alerts = alerts.slice(-20);
        global.set('edge_recentAlerts', alerts);
    }
    commStatus[devId] = status;
    global.set('edge_commStatus', commStatus);

    // Re-publish last-good values with BAD quality (throttled: max every 30s)
    var shouldSendBad = !lastBadSend[devId] || (nowMs - lastBadSend[devId] > 30000);
    var mqttMsg = null;
    if (shouldSendBad && lastGoodTags[devId] && lastGoodTags[devId].length > 0) {
        lastBadSend[devId] = nowMs;
        global.set('edge_lastBadSend', lastBadSend);
        var badVals = JSON.parse(JSON.stringify(lastGoodTags[devId]));
        badVals.forEach(function (v) { v.quality = 1; });
        mqttMsg = {
            topic: 'edgelink-v10/data/' + nodeId + '/' + devId,
            payload: JSON.stringify({
                node_id: nodeId,
                device_id: devId,
                device_name: devName,
                host_pc_ip: hostPcIp,
                ts: now,
                value_count: badVals.length,
                values: badVals,
                quality: 'BAD'
            }),
            qos: 1,
            retain: false
        };
    }

    delete procGuard[devId];
    global.set('edge_proc_guard', procGuard);
    // Send alarm + BAD data as array so mqtt-out publishes both
    var mqttOut = alarmMsg ? (mqttMsg ? [alarmMsg, mqttMsg] : [alarmMsg]) : (mqttMsg || null);
    node.send([mqttOut, null]);
    node.status({ fill: 'red', shape: 'ring', text: devName + ' OFFLINE' });
    return;
}

// ===== SUCCESS PATH =====

// Reset comm status on success
var prevStatus = commStatus[devId] || { consecutiveFails: 0, lastState: 'online' };
var wasOffline = prevStatus.lastState === 'offline';
commStatus[devId] = { consecutiveFails: 0, lastState: 'online', lastSuccessTime: nowMs };
global.set('edge_commStatus', commStatus);

// P0-3: Push to pending on recovery (offline → online)
if (wasOffline) {
    commPending.push({
        deviceId: devId,
        success: true,
        error: '',
        consecutiveFails: 0,
        ts: now
    });
    global.set('edge_commPending', commPending);
    if (DEBUG) node.warn('[DP] Device ' + devName + ' state: offline → online (recovered)');
}

var stdData = result.data || {};
var tagValues = [];
var pgRecords = [];
var validCount = 0;
var skippedCount = 0;

// Process each tag
(devTags.length > 0 ? devTags : []).forEach(function (tag) {
    var entry = stdData[tag.id];
    if (!entry || entry.rawValue === undefined || entry.rawValue === null) {
        // Tag not in this read, mark as missing
        tagValues.push({
            tag_id: tag.id,
            tag_address: tag.regAddr || '',
            tag_name: tag.name || '',
            raw_value: null,
            eng_value: null,
            unit: tag.unit || '',
            quality: 2,
            ts: now
        });
        return;
    }

    // Step 1: Transform (slope/offset, linear)
    var eng = entry.rawValue;
    var tform = tag.tform || tag.transformType || 'none';
    if (tform === 'slope_offset' || tform === 'linear') {
        eng = entry.rawValue * (tag.slope || tag.transformSlopeA || 1) + (tag.offset || tag.transformOffsetB || 0);
    }
    eng = parseFloat(parseFloat(eng).toFixed(2));

    // Step 2: Deadband filtering
    var prevVals = lastGoodTags[devId] || [];
    var prev = null;
    for (var pi = 0; pi < prevVals.length; pi++) {
        if (prevVals[pi].tag_id === tag.id) { prev = prevVals[pi]; break; }
    }
    var deadband = tag.deadband || 0;
    var forceInterval = tag.reportForceIntervalMs || 5000;

    if (prev && deadband > 0) {
        var delta = Math.abs(eng - (prev.eng_value || 0));
        var prevTs = prev.ts ? new Date(prev.ts).getTime() : 0;
        if (delta < deadband && (nowMs - prevTs) < forceInterval) {
            skippedCount++;
            return; // Skip: value within deadband, not forced yet
        }
    }

    // Step 3: Quality code
    var quality = entry.quality || 0;

    var tv = {
        tag_id: tag.id,
        tag_address: tag.regAddr || '',
        tag_name: tag.name || '',
        raw_value: entry.rawValue,
        eng_value: eng,
        unit: tag.unit || '',
        quality: quality,
        ts: now
    };
    tagValues.push(tv);
    validCount++;

    // Step 4: PG record
    pgRecords.push({
        ts: now,
        node_id: nodeId,
        device_id: devId,
        device_name: devName,
        tag_id: tag.id,
        tag_address: tag.regAddr || '',
        tag_name: tag.name || '',
        raw_value: entry.rawValue,
        eng_value: eng,
        unit: tag.unit || '',
        quality: quality,
        host_pc_ip: hostPcIp
    });

    // Step 5: History cache
    if (!historyData[devId]) historyData[devId] = {};
    if (!historyData[devId][tag.id]) historyData[devId][tag.id] = [];
    historyData[devId][tag.id].push({ ts: now, raw: entry.rawValue, eng: eng, q: quality });
    if (historyData[devId][tag.id].length > 100) {
        historyData[devId][tag.id] = historyData[devId][tag.id].slice(-100);
    }
});

// Update lastGoodTags (only for successfully read tags)
if (tagValues.length > 0) {
    lastGoodTags[devId] = tagValues.filter(function (v) { return v.quality !== 2; });
    global.set('edge_lastGoodTags', lastGoodTags);
}
global.set('edge_historyData', historyData);

// PG success counter is incremented by sf-pg-writer after successful write only

// === Build outputs ===
var mqttMsg = null;
if (tagValues.length > 0) {
    mqttMsg = {
        topic: 'edgelink-v10/data/' + nodeId + '/' + devId,
        payload: JSON.stringify({
            node_id: nodeId,
            device_id: devId,
            device_name: devName,
            host_pc_ip: hostPcIp,
            ts: now,
            value_count: validCount,
            values: tagValues
        }),
        qos: 1,
        retain: false
    };
}

var pgMsg = null;
if (pgRecords.length > 0) {
    pgMsg = { payload: { pgRecords: pgRecords } };
}

if (DEBUG && validCount > 0) {
    node.status({ fill: 'green', shape: 'dot', text: devName + ' ' + validCount + ' vals' + (skippedCount > 0 ? ' (' + skippedCount + ' skipped)' : '') });
}

delete procGuard[devId];
global.set('edge_proc_guard', procGuard);
node.send([mqttMsg, pgMsg]);
return;

// === sf-pg-writer v10: 事件驱动队列 + 自适应批量 ===
var pg = global.get('pg');
var DEBUG = global.get('edge_debug') || false;
var MAX_QUEUE = 10000;  // Max queue size before dropping
var BATCH_SIZE = 200;    // Default batch size, adjusted dynamically

var records = (msg.payload && msg.payload.pgRecords) ? msg.payload.pgRecords : [];
if (records.length === 0) {
    node.status({ fill: 'grey', shape: 'dot', text: 'no records' });
    return null;
}

// === Enqueue ===
var queue = global.get('edge_pg_queue') || [];
var totalLen = queue.length + records.length;

if (totalLen > MAX_QUEUE) {
    var dropCount = totalLen - MAX_QUEUE;
    queue = queue.slice(dropCount);  // Drop oldest
    node.warn('[PG-Writer] Queue overflow! Dropped ' + dropCount + ' oldest records. Current: ' + queue.length);
    // Alert via global for sf-monitor to pick up
    var alerts = global.get('edge_recentAlerts') || [];
    alerts.push({
        alertType: 'PG_QUEUE_OVERFLOW',
        deviceId: 0,
        deviceName: 'PG-Writer',
        msg: 'Queue overflow, dropped ' + dropCount + ' records',
        ts: new Date().toISOString()
    });
    if (alerts.length > 20) alerts = alerts.slice(-20);
    global.set('edge_recentAlerts', alerts);
}

queue = queue.concat(records);
global.set('edge_pg_queue', queue);

if (DEBUG) node.status({ fill: 'yellow', shape: 'dot', text: 'Q:' + queue.length });

// === Event-driven write: trigger only if not already writing ===
if (global.get('edge_pg_writing')) {
    // Write in progress, data will be picked up after current batch completes
    return null;
}

// Start writing
startWrite();
return null;

// ===== Internal write function =====
function startWrite() {
    global.set('edge_pg_writing', true);
    doWrite();
}

function doWrite() {
    var q = global.get('edge_pg_queue') || [];
    if (q.length === 0) {
        global.set('edge_pg_writing', false);
        node.status({ fill: 'green', shape: 'dot', text: 'idle' });
        return;
    }

    // Adaptive batch size: bigger queue → bigger batch
    var batchSize = BATCH_SIZE;
    if (q.length > 5000) batchSize = 500;
    else if (q.length > 2000) batchSize = 300;

    var batch = q.splice(0, batchSize);
    global.set('edge_pg_queue', q);

    node.status({ fill: 'yellow', shape: 'dot', text: 'writing ' + batch.length + '/' + q.length });

    // Check if pg module is available
    if (!pg) {
        // No PG driver — just count and clear (development mode)
        if (DEBUG) node.warn('[PG-Writer] pg not available, discarding ' + batch.length + ' records (dev mode)');
        var total = global.get('edge_pg_success_count') || 0;
        global.set('edge_pg_success_count', total + batch.length);
        finishWrite(true);
        return;
    }

    // Build parameterized INSERT
    var valStrs = [];
    var params = [];
    var idx = 0;
    batch.forEach(function (r) {
        var qStr = r.quality === 0 ? 'GOOD' : (r.quality === 1 ? 'BAD' : 'UNCERTAIN');
        var vals = [
            r.device_id, r.tag_id, r.node_id,
            r.raw_value, r.eng_value, qStr, r.ts || new Date().toISOString()
        ];
        var placeholders = vals.map(function () { idx++; return '$' + idx; });
        valStrs.push('(' + placeholders.join(',') + ')');
        params = params.concat(vals.map(function (v) { return v === undefined ? null : v; }));
    });

    var sql = 'INSERT INTO plc_data_log '
        + '(device_id,tag_id,node_id,raw_value,eng_value,quality,ts) VALUES ' + valStrs.join(',');

    // Acquire/reuse pg pool
    var pool = getPool();
    if (!pool) {
        // No pool available — discard, don't requeue (avoids infinite loop)
        global.set('edge_pg_writing', false);
        node.status({ fill: 'red', shape: 'ring', text: 'no pool' });
        return;
    }

    var writeStart = Date.now();
    pool.query({ text: sql, values: params }, function (err, result) {
        var elapsed = Date.now() - writeStart;
        if (err) {
            node.warn('[PG-Writer] Write failed (' + elapsed + 'ms): ' + err.message);
            node.status({ fill: 'red', shape: 'ring', text: 'FAIL ' + err.message.substring(0, 20) });
            finishWrite(false, batch);
            return;
        } else {
            var count = result.rowCount || batch.length;
            var total = global.get('edge_pg_success_count') || 0;
            global.set('edge_pg_success_count', total + count);
            global.set('edge_pg_last_latency_ms', elapsed);
            if (DEBUG) node.status({ fill: 'green', shape: 'dot', text: count + ' OK ' + elapsed + 'ms' });
        }

        // Adaptive: if write latency > 200ms, reduce batch size for next round
        if (elapsed > 200 && BATCH_SIZE > 50) {
            BATCH_SIZE = Math.max(50, BATCH_SIZE - 25);
        } else if (elapsed < 50 && BATCH_SIZE < 500) {
            BATCH_SIZE = Math.min(500, BATCH_SIZE + 25);
        }

        // Event-driven: continue if queue has more data
        finishWrite(!err);
    });
}

function getPool() {
    var pool = global.get('edge_pgPool');
    var wanted = {
        host: global.get('edge_pgHost') || '127.0.0.1',
        port: global.get('edge_pgPort') || 5432,
        database: global.get('edge_pgDatabase') || 'edgelink',
        user: global.get('edge_pgUser') || 'postgres',
        password: global.get('edge_pgPassword') || '',
        max: 5
    };

    if (pool) {
        var current = pool.options;
        if (current.host === wanted.host && current.port === wanted.port &&
            current.database === wanted.database && current.user === wanted.user &&
            current.password === wanted.password) {
            return pool;
        }
        try { pool.end(); } catch (e) {}
        pool = null;
    }

    if (!pg) return null;
    if (!wanted.password) {
        node.error('[PG-Writer] PG password not configured in settings.js (edge_pgPassword)');
        return null;
    }
    try {
        pool = new pg.Pool(wanted);
        pool.on('error', function (e) {
            node.warn('[PG-Writer] Pool error: ' + e.message);
            global.set('edge_pgPool', null);
        });
        global.set('edge_pgPool', pool);
        return pool;
    } catch (e) {
        node.warn('[PG-Writer] Cannot create pool: ' + e.message);
        global.set('edge_pgPool', null);
        return null;
    }
}

function finishWrite(ok, failedBatch) {
    if (!ok) {
        // Requeue failed batch at head, retry after backoff (5s)
        global.set('edge_pg_writing', false);
        var q = global.get('edge_pg_queue') || [];
        global.set('edge_pg_queue', q.concat(failedBatch || []));
        node.status({ fill: 'red', shape: 'ring', text: 'retry in 5s' });
        setTimeout(function () {
            if (!global.get('edge_pg_writing')) startWrite();
        }, 5000);
        return;
    }
    var q = global.get('edge_pg_queue') || [];
    if (q.length > 0) {
        // More data waiting — continue immediately (event-driven, only on success)
        doWrite();
    } else {
        // Queue empty — go idle, wait for next input
        global.set('edge_pg_writing', false);
        node.status({ fill: 'green', shape: 'dot', text: 'idle' });
    }
}

