        var p = 'node_id=' + nodeId + '&device_id=' + item.deviceId
            + '&success=' + (item.success ? 'true' : 'false')
            + '&error_msg=' + encodeURIComponent(item.error || '');
        var opts = {
            hostname: HOST, port: PORT, path: '/monitor/device-comm?' + p, method: 'POST',
            headers: { 'X-API-Key': apiKey, 'Authorization': 'Bearer ' + jwt, 'Content-Type': 'application/json' }
        };
        var req = http.request(opts, function (res) {
            if (res.statusCode === 401 && !reauthNeeded) reauthNeeded = true;
            res.resume();
        });
        req.setTimeout(3000, function () { req.destroy(); });
        req.on('error', function () {});
        req.write('{}');
        req.end();
    });
}

