        timeout: d.commTimeoutMs || d.timeout || 3000,
        maxRetries: d.retryCount || d.maxRetries || 2,
        retryInterval: d.retryIntervalMs || d.retryInterval || 300,
        triggerKind: d.triggerKind || 1
    });
});

global.set('edge_deviceLastScan', deviceLastScan);

if (activeDevices.length === 0) {
    var st = devices.length + ' devs';
    if (skippedTrig2 > 0) st += ' (' + skippedTrig2 + ' unchanged)';
    if (skippedTrig1 > 0) st += ' (' + skippedTrig1 + ' not-due)';
    if (skippedHandshake > 0) st += ' (' + skippedHandshake + ' wait-trigger)';
    node.status({ fill: 'green', shape: 'dot', text: st });
    return null;
}

return activeDevices.map(function (d) { return { payload: d }; });

// === comType 分流: MC_Protocol → Output1, Modbus_TCP → Output2 ===
var dev = msg.payload;
if (!dev || !dev.comType) { return null; }

if (dev.comType === 'Modbus_TCP') {
    return [null, { payload: dev }];
}
// Default: MC_Protocol or any unrecognized → MC driver
return [{ payload: dev }, null];

var deviceId = 0;
try {
    var p = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
    deviceId = p.deviceId || 0;
} catch (e) {
    var m = (msg.topic || '').match(/edgelink-v10\/trigger\/scan\/(\d+)/);
    if (m) deviceId = parseInt(m[1]) || 0;
}
if (deviceId > 0) {
    var flags = global.get('edge_handshakeFlags') || {};
    flags[deviceId] = true;
    global.set('edge_handshakeFlags', flags);
    if (global.get('edge_debug')) node.warn('[Handshake] Triggered scan for device ' + deviceId);
}
return null;

// 配置完成后通知调度器可以开始采集
// msg.payload 包含 config 信息，调度器从 edge_devices 读取
var DEBUG = global.get('edge_debug') || false;
if (DEBUG) node.warn('[Main] Config ready, devices=' + (global.get('edge_devices') || []).length);
return msg;

// === v10 调度器: 读 edge_devices, triggerKind过滤, 输出单设备消息 ===
var configReady = global.get('edge_configReady') || false;
if (!configReady) { node.status({ fill: 'grey', shape: 'dot', text: 'wait config' }); return null; }

var devices = global.get('edge_devices') || [];
if (devices.length === 0) { node.status({ fill: 'grey', shape: 'dot', text: 'no devices' }); return null; }

var now = Date.now();
var deviceLastScan = global.get('edge_deviceLastScan') || {};

var DEBUG = global.get('edge_debug') || false;
var handshakeFlags = global.get('edge_handshakeFlags') || {};
var triggerLastRaw = global.get('edge_triggerLastRaw') || {};
var triggerForceTimes = global.get('edge_triggerForceTimes') || {};
var lastGoodTags = global.get('edge_lastGoodTags') || {};

var activeDevices = [];
var skippedTrig2 = 0;
var skippedTrig1 = 0;
var skippedHandshake = 0;

devices.forEach(function (d) {
    if (d.triggerKind === 0) {
        if (!handshakeFlags[d.id]) { skippedHandshake++; return; }
        delete handshakeFlags[d.id];
        global.set('edge_handshakeFlags', handshakeFlags);
        // Handshake-triggered: bypass interval, collect immediately
        deviceLastScan[d.id] = now;
        activeDevices.push({
            id: d.id, deviceName: d.deviceName, comType: d.comType,
            plcIp: d.plcIp, plcPort: d.plcPort,
            protocolParams: d.protocolParams || {},
            tags: d.tags || [],
            timeout: d.commTimeoutMs || d.timeout || 3000,
            maxRetries: d.retryCount || d.maxRetries || 2,
            retryInterval: d.retryIntervalMs || d.retryInterval || 300,
            triggerKind: d.triggerKind || 1
        });
        return;
    }
    if (d.triggerKind === 2) {
        var forceDue = !triggerForceTimes[d.id] || (now - triggerForceTimes[d.id] >= 5000);
        if (!forceDue && lastGoodTags[d.id]) {
            var prevVals = triggerLastRaw[d.id] || {};
            var changed = false;
            for (var i = 0; i < lastGoodTags[d.id].length; i++) {
                if (prevVals[lastGoodTags[d.id][i].tag_id] !== lastGoodTags[d.id][i].raw_value) { changed = true; break; }
            }
            if (!changed) { skippedTrig2++; return; }
        }
        if (forceDue) { triggerForceTimes[d.id] = now; global.set('edge_triggerForceTimes', triggerForceTimes); }
        if (lastGoodTags[d.id]) {
            var newVals = {};
            lastGoodTags[d.id].forEach(function (v) { newVals[v.tag_id] = v.raw_value; });
            triggerLastRaw[d.id] = newVals;
            global.set('edge_triggerLastRaw', triggerLastRaw);
        }
    }
    // Per-device scan interval
    var dInt = d.scanIntervalMs || 1000;
    var dLast = deviceLastScan[d.id] || 0;
    if (now - dLast < dInt) { skippedTrig1 = (skippedTrig1 || 0) + 1; return; }
    deviceLastScan[d.id] = now;

    activeDevices.push({
        id: d.id, deviceName: d.deviceName, comType: d.comType,
        plcIp: d.plcIp, plcPort: d.plcPort,
        protocolParams: d.protocolParams || {},
        tags: d.tags || [],
        timeout: d.commTimeoutMs || d.timeout || 3000,
        maxRetries: d.retryCount || d.maxRetries || 2,
        retryInterval: d.retryIntervalMs || d.retryInterval || 300,
        triggerKind: d.triggerKind || 1
    });
});

global.set('edge_deviceLastScan', deviceLastScan);

if (activeDevices.length === 0) {
    var st = devices.length + ' devs';
    if (skippedTrig2 > 0) st += ' (' + skippedTrig2 + ' unchanged)';
    if (skippedTrig1 > 0) st += ' (' + skippedTrig1 + ' not-due)';
    if (skippedHandshake > 0) st += ' (' + skippedHandshake + ' wait-trigger)';
    node.status({ fill: 'green', shape: 'dot', text: st });
    return null;
}

return activeDevices.map(function (d) { return { payload: d }; });

// MQTT payload: {"deviceId":23} → 设置 edge_handshakeFlags[23]
var deviceId = 0;
try {
    var p = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
    deviceId = p.deviceId || 0;
} catch (e) {
    var m = (msg.topic || '').match(/edgelink-v10\/trigger\/scan\/(\d+)/);
    if (m) deviceId = parseInt(m[1]) || 0;
}
if (deviceId > 0) {
    var flags = global.get('edge_handshakeFlags') || {};
    flags[deviceId] = true;
    global.set('edge_handshakeFlags', flags);
    if (global.get('edge_debug')) node.warn('[Handshake] Triggered scan for device ' + deviceId);
}
return null;

// === Phase 1a: 初始化 edge_ 全局变量 ===
if (!global.get('edge_initialized')) {
    global.set('edge_nodeId', global.get('edge_nodeId') || 999);
    global.set('edge_hostPcIp', global.get('edge_hostPcIp') || '127.0.0.1');
    global.set('edge_tagConfigs', global.get('edge_tagConfigs') || {
        1: [
            { id: 101, addr: 100, regAddr: 'D100', regType: 'D', name: '温度', tform: 'linear', slope: 0.1, offset: 0, unit: '℃', deadband: 0.5, reportForceIntervalMs: 5000 },
            { id: 102, addr: 101, regAddr: 'D101', regType: 'D', name: '压力', tform: 'none', slope: 1, offset: 0, unit: 'kPa', deadband: 0, reportForceIntervalMs: 5000 },
            { id: 103, addr: 10, regAddr: 'X10', regType: 'X', name: '启动信号', tform: 'none', slope: 1, offset: 0, unit: '', deadband: 0, reportForceIntervalMs: 5000 }
        ]
    });
    global.set('edge_simulationMode', global.get('edge_simulationMode') !== undefined ? global.get('edge_simulationMode') : true);
    global.set('edge_debug', global.get('edge_debug') !== undefined ? global.get('edge_debug') : true);
    global.set('edge_commStatus', {});
    global.set('edge_lastGoodTags', {});
    global.set('edge_historyData', {});
    global.set('edge_pg_queue', []);
    global.set('edge_pg_success_count', 0);
    global.set('edge_commPending', []);
    global.set('edge_lastBadSend', {});
    global.set('edge_handshakeFlags', {});
    global.set('edge_initialized', true);
    node.warn('[V10-Main] Globals initialized, simulationMode=' + global.get('edge_simulationMode'));
}

// Pass device payload to MC driver
return msg;
